begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_function('public','get_plan_revision_for_owner',array['uuid','date','uuid'],'exact historical revision reads retain owner RLS');
select ok(pg_get_functiondef('public.get_planner_generation_input(uuid,date,date)'::regprocedure) like '%planner-input-v2%', 'generation atomically declares nutrition input capability');
select ok(pg_get_functiondef('public.get_planner_generation_input(uuid,date,date)'::regprocedure) like '%nutritionSetup%', 'generation includes explicit nutrition profiles');
select has_function('private','enforce_whole_unit_pantry_write',array[]::text[],'whole pantry units validated on writes');

insert into auth.users(id,email) values('85000000-0000-4000-8000-000000000001','whole-unit-owner@example.test');
insert into public.households(id,owner_user_id,weekly_plan_budget_vnd,max_elapsed_minutes) values('85000000-0000-4000-8000-000000000002','85000000-0000-4000-8000-000000000001',700000,30);
insert into public.foods(id,code,name_vi,base_dimension,base_unit_id) select '85000000-0000-4000-8000-000000000003','whole_egg_mass','Trứng cân theo gam','mass',id from public.units where code='g';
insert into public.food_fact_versions(id,food_id,version_number,category_id,edible_fraction,provenance,created_by) select '85000000-0000-4000-8000-000000000004','85000000-0000-4000-8000-000000000003',1,id,1,'Whole unit fixture','85000000-0000-4000-8000-000000000001' from public.food_categories where code='staple';
insert into public.food_fact_unit_conversions(food_fact_version_id,unit_id,base_quantity_per_unit,gross_grams_per_unit,display_step,provenance) select '85000000-0000-4000-8000-000000000004',id,case when code='item' then 50 else 1 end,case when code='item' then 50 else 1 end,1,'Measured fixture one egg 50g' from public.units where code in ('g','item');
select private.begin_catalog_transition();
update public.food_fact_versions set publication_status='published',content_hash=repeat('a',64),published_at=now(),assessment_completed_at=now() where id='85000000-0000-4000-8000-000000000004';
update public.foods set status='published',current_fact_version_id='85000000-0000-4000-8000-000000000004' where id='85000000-0000-4000-8000-000000000003';
select private.end_catalog_transition();
insert into public.pantry_items(household_id,food_id,food_fact_version_id,unit_id,quantity) select '85000000-0000-4000-8000-000000000002','85000000-0000-4000-8000-000000000003','85000000-0000-4000-8000-000000000004',id,2.4 from public.units where code='item';
insert into public.food_quantity_policy_versions(id,food_id,food_fact_version_id,version_number,base_unit_id,base_dimension,food_form,step_base_quantity,rounding,provenance,created_by) select '85000000-0000-4000-8000-000000000005','85000000-0000-4000-8000-000000000003','85000000-0000-4000-8000-000000000004',1,id,'mass','whole_piece',100,'ceil','Measured fixture 2-piece cooking quantum','85000000-0000-4000-8000-000000000001' from public.units where code='g';
select private.begin_catalog_transition();
update public.food_quantity_policy_versions set publication_status='published',content_hash=repeat('b',64),published_at=now() where id='85000000-0000-4000-8000-000000000005';
select private.end_catalog_transition();
select is((select quantity from public.pantry_items where food_id='85000000-0000-4000-8000-000000000003'),2.4::numeric,'published policy does not rewrite legacy fractional stock');
select throws_ok($$update public.pantry_items set quantity=2.4 where food_id='85000000-0000-4000-8000-000000000003'$$,'23514','INVALID_INDIVISIBLE_PANTRY_QUANTITY','new fractional item write is rejected');
select throws_ok($$update public.pantry_items set quantity=125,unit_id=(select id from public.units where code='g') where food_id='85000000-0000-4000-8000-000000000003'$$,'23514','INVALID_INDIVISIBLE_PANTRY_QUANTITY','changing to grams cannot bypass whole pieces');
select set_config('bepnha.shopping_transition_revision','85000000-0000-4000-8000-000000000099',true);
select throws_ok($$update public.pantry_items set quantity=2.4 where food_id='85000000-0000-4000-8000-000000000003'$$,'23514','INVALID_INDIVISIBLE_PANTRY_QUANTITY','forged setting does not create protected legacy context');
select lives_ok($$update public.pantry_items set quantity=1 where food_id='85000000-0000-4000-8000-000000000003'$$,'one physical piece in stock remains valid when cooking quantum is two pieces');
select is((select base_quantity from public.pantry_items where food_id='85000000-0000-4000-8000-000000000003'),50::numeric,'actual one-piece conversion remains authoritative');
select ok(not has_function_privilege('authenticated','private.begin_plan_transition()','execute'),'owners cannot create trusted legacy bypass context');
select ok(not has_function_privilege('anon','public.get_plan_revision_for_owner(uuid,date,uuid)','execute'),'historical private revision read excludes anonymous users');
select * from finish();
rollback;
